"MINUTE\"\n },\n {\n  \"id\": \"AMD-G03\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"10:21-10:25\",\n  \"expect\": \"WAIT/AVOID\",\n  \"allowed\": [\n   \"WATCH\",\n   \"SETUP\",\n   \"ARMED\",\n   \"AVOID\"\n  ],\n  \"forbidden\": [\n   \"READY\",\n   \"ACTIVE\"\n  ],\n  \"note\": \"No blind zone-buy\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G04\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"10:51-10:53\",\n  \"expect\": \"BUY after reclaim/hold\",\n  \"allowed\": [\n   \"READY\",\n   \"ACTIVE\",\n   \"ARMED\"\n  ],\n  \"forbidden\": [],\n  \"note\": \"False-negative test\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G05\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"11:59\",\n  \"expect\": \"BUY\",\n  \"allowed\": [\n   \"READY\",\n   \"ACTIVE\"\n  ],\n  \"forbidden\": [],\n  \"note\": \"Valid continuation\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G06\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"12:17\",\n  \"expect\": \"WAIT/AVOID\",\n  \"allowed\": [\n   \"WATCH\",\n   \"SETUP\",\n   \"ARMED\",\n   \"AVOID\"\n  ],\n  \"forbidden\": [\n   \"READY\",\n   \"ACTIVE\"\n  ],\n  \"note\": \"Pullback still falling\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G07\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"12:27\",\n  \"expect\": \"BUY if reclaim/hold valid\",\n  \"allowed\": [\n   \"READY\",\n   \"ACTIVE\",\n   \"ARMED\"\n  ],\n  \"forbidden\": [],\n  \"note\": \"Reclaimed pullback\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G08\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"13:03\",\n  \"expect\": \"WAIT/AVOID\",\n  \"allowed\": [\n   \"WATCH\",\n   \"SETUP\",\n   \"ARMED\",\n   \"AVOID\"\n  ],\n  \"forbidden\": [\n   \"READY\",\n   \"ACTIVE\"\n  ],\n  \"note\": \"Needs reset after weakness/failure\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G09\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"15:30-15:31\",\n  \"expect\": \"BUY\",\n  \"allowed\": [\n   \"READY\",\n   \"ACTIVE\"\n  ],\n  \"forbidden\": [],\n  \"note\": \"Base -> expansion/reclaim -> continuation; entry 472.25-472.50\",\n  \"kind\": \"MINUTE\"\n },\n {\n  \"id\": \"AMD-G10\",\n  \"symbol\": \"AMD\",\n  \"date\": \"2026-09-04\",\n  \"time\": \"15:43-15:44\",\n  \"expect\": \"ADVANCE/STAY ACTIONABLE\",\n  \"allowed\": [\n   \"ARMED\",\n   \"READY\",\n   \"ACTIVE\"\n  ],\n  \"forbidden\": [\n   \"AVOID\"\n  ],\n  \"note\": \"Confirmation satisfied must not regress without invalidation\",\n  \"kind\": \"MINUTE\"\n }\n];\n  function runGolden(){\n    var keys=Object.keys(datasets);\n    if(!keys.length){toast('טען CSV קודם');return}\n    var out=[],skipped=0;\n    GOLDEN.forEach(function(c){\n      var d=datasets[c.symbol+'|'+c.date];\n      if(!d){skipped++;return}\n      // PREFIX ONLY. The engine never sees a candle past the golden minute.\n      var prefix=d.rows.filter(function(r){return r.time<=c.time});\n      if(!prefix.length){skipped++;return}\n      var st=runV2(prefix,{computeBars:computeBars,decide:decide},{});\n      var s=st[st.length-1];\n      var dec=(s.state==='READY'||s.state==='ACTIVE')?'BUY':s.state==='AVOID'?'AVOID':'WAIT';\n      var allowedOk=!c.allowed.length||c.allowed.indexOf(s.state)>=0;\n      var forbidden=c.forbidden.indexOf(s.state)>=0;\n      // and the same minute with an absurd future appended must not move\n      var junk=d.rows.filter(function(r){return r.time>c.time}).map(function(r,i){\n        return {symbol:r.symbol,date:r.date,time:r.time,unix:r.unix,\n          open:1+i,high:500+i,low:0.5,close:250+i,volume:1}});\n      var j=runV2(prefix.concat(junk),{computeBars:computeBars,decide:decide},{})[prefix.length-1];\n      var fp=function(x){return JSON.stringify([x.state,x.score,x.setupId,x.reason,x.next,x.plan])};\n      var leak=fp(j)!==fp(s);\n      out.push({id:c.id,symbol:c.symbol,time:c.time,note:c.note,\n        expected:c.expect,allowed:c.allowed.join('|'),actual:dec,state:s.state,score:s.score,\n        setupId:s.setupId,plan:s.plan,reason:s.reason,leak:leak,\n        pass:allowedOk&&!forbidden&&!leak,quality:s.quality&&s.quality.label});\n    });\n    drawGolden(out,skipped);\n  }\n  function drawGolden(out,skipped){\n    var p=out.filter(function(x){return x.pass}).length;\n    var h='<div class=\"sec\">GOLDEN QA — '+p+'/'+out.length+' PASS'+(skipped?' · '+skipped+' לא רצו (אין דאטה)':'')+'</div>'+\n      '<div class=\"scroll\"><table><thead><tr><th>ID</th><th>שעה</th><th>ציפייה</th><th>בפועל</th><th>מצב</th>'+\n      '<th>ציון</th><th>איכות</th><th>דליפה</th><th>תוצאה</th><th>סיבה</th></tr></thead><tbody>';\n    out.forEach(function(x){\n      h+='<tr class=\"'+(x.pass?'win':'loss')+'\"><td>'+x.id+'</td><td>'+x.time+'</td>'+\n        '<td>'+x.expected+'</td><td>'+x.actual+'</td><td>'+x.state+'</td><td>'+x.score+'</td>'+\n        '<td>'+(x.quality||'—')+'</td><td>'+(x.leak?'FAIL':'ok')+'</td>'+\n        '<td>'+(x.pass?'PASS':'FAIL')+'</td><td style=\"white-space:normal;text-align:right\">'+(x.reason||'')+'</td></tr>';\n    });\n    qs('#golden').innerHTML=h+'</tbody></table></div>';\n    qs('#golden').hidden=false;\n    qs('#goldenDl').hidden=false;\n    window.__golden=out;\n  }\n  qs('#goldenDl').onclick=function(){\n    var o=window.__golden||[];\n    var csv=['test_id,symbol,time,expected_decision,expected_allowed_states,actual_decision,actual_state,score,setup_id,entry,stop,t1,t2,rr,leakage,pass,notes']\n      .concat(o.map(function(x){return [x.id,x.symbol,x.time,x.expected,x.allowed,x.actual,x.state,x.score,\n        x.setupId||'',x.plan?x.plan.entry:'',x.plan?x.plan.stop:'',x.plan?x.plan.t1:'',x.plan?x.plan.t2:'',\n        x.plan?x.plan.rr:'',x.leak?'FAIL':'ok',x.pass?'PASS':'FAIL',JSON.stringify(x.note)].join(',')})).join('\\n');\n    var b=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');\n    a.href=URL.createObjectURL(b); a.download='qa-golden-results.csv'; a.click();\n  };\n\n  loadSymbols().then(loadDay).catch(function(e){\n    qs('#live').innerHTML='<div class=\"msg\">לא הצלחתי לטעון: '+e+'</div>'});\n})();\n</script>\n</body>\n</html>\n";
